<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{row.displayName||'平台接收关系'}}</h2><p v-if="selected"><StatusTag :value="row.state"/> {{status(row.mode)}} · {{row.enabled?'本地启用':'本地停用'}} · <span class="ui-meta">{{row.id}} / v{{row.version}}</span></p></div><Button @click="back">返回列表</Button></header><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><template v-if="selected"><Tabs v-model="tab"><TabPane label="关系与核验事实" name="overview"><DetailSection title="平台关系"><FieldRow label="平台主体" :value="row.displayName"/><FieldRow label="收付通配置" :value="configName"/><FieldRow label="模式" :value="status(row.mode)"/><FieldRow label="关系类型" :value="status(row.relationType)"/><FieldRow label="接收方类型" :value="status(row.receiverType)"/><FieldRow label="接收账号" value="受控保存，不向页面返回账号"/><FieldRow label="核验状态" :value="status(row.state)"/><FieldRow label="核验来源" :value="status(row.trustSource)"/><FieldRow label="核验时间" :value="date(row.verifiedAt)"/><FieldRow label="当前原因" :value="row.reason" wide/></DetailSection><Alert show-icon>关系核验与本地启停分别保存。停用使引用关系的资格重新判断；不会删除历史，也不会执行分账。</Alert></TabPane><TabPane label="操作历史" name="history"><Table :data="selected.operations" :columns="columns" no-data-text="暂无渠道操作"><template slot="action" slot-scope="{row}">{{action(row.action)}}</template><template slot="state" slot-scope="{row}"><StatusTag :value="row.status"/></template><template slot="reason" slot-scope="{row}">{{row.failureCode?reason(row.failureCode):'未提供失败原因'}}</template><template slot="time" slot-scope="{row}">{{date(row.completedAt||row.createdAt)}}</template></Table></TabPane></Tabs><footer class="ui-footer-actions"><Button @click="back">返回列表</Button><Button :disabled="blocked||row.mode!=='MOCK'" @click="execute('sync')">{{row.state==='UNKNOWN'?'按原关系回查核验':'同步核验关系'}}</Button><Button :disabled="blocked" @click="execute(row.enabled?'disable':'enable')">{{row.enabled?'停用关系':'启用已核验关系'}}</Button></footer></template></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';import DetailSection from './components/DetailSection';import FieldRow from './components/FieldRow';export default {mixins:[page],components:{PageStatus,StatusTag,DetailSection,FieldRow},data:()=>({configName:'配置名称读取中',columns:[{title:'操作',slot:'action',minWidth:170},{title:'结果',slot:'state',minWidth:130},{title:'失败原因',slot:'reason',minWidth:250},{title:'时间',slot:'time',minWidth:185}]}),computed:{row(){return this.selected&&this.selected.receiver||{};}},mounted(){this.reload();},watch:{'$route.params.id'(){this.reload();}},methods:{reload(){return this.latest(async()=>{const v=await this.read('/receivers/'+this.$route.params.id),c=await this.ui('/lookups/channel-configs',{selected:v.receiver.configId,pageSize:1});return {v,name:c.records[0]&&c.records[0].name};},r=>{this.selected=r.v;this.configName=r.name||'配置名称不可读';},()=>{this.selected=null;});},async execute(action){const row=this.row,result=await this.command('/receivers/'+row.id+'/'+action,{sync:'同步核验平台接收关系',enable:'启用已核验接收关系',disable:'停用平台接收关系'}[action],{expectedVersion:row.version},row.displayName+' · '+this.status(row.mode)+' · v'+row.version+'。仅本地测试模式允许同步，不执行资金。');if(result)await this.reload();}}};</script>
